"""Write docs/tools.md: every tool the models see, with its description and argument schema.

    uv run python scripts/dump_tools.py

The descriptions are part of what the evaluated models read; they are reviewed by the
author before the freeze (plan §2 #5: English, identical across columns and models).
"""

import json
import sys
from pathlib import Path

from afandem.sandbox import DOMAINS

OUT = Path(__file__).resolve().parent.parent / "docs" / "tools.md"


def main() -> int:
    lines = [
        "# Tools the models see",
        "",
        "Generated by `scripts/dump_tools.py` from the sandbox registries. Descriptions and",
        "argument schemas are sent to every model, in English, identically for all six text",
        "columns. **Status: draft descriptions, to be reviewed by Aya before the freeze.**",
        "",
    ]
    for domain, (_, registry) in DOMAINS.items():
        mutating = set(registry.mutating())
        lines += [f"## {domain}", ""]
        for spec in registry.tools_json():
            fn = spec.get("function", spec)
            kind = "writes" if fn["name"] in mutating else "reads"
            lines += [
                f"### `{fn['name']}` ({kind})",
                "",
                fn["description"],
                "",
                "```json",
                json.dumps(fn["parameters"], ensure_ascii=False, indent=2),
                "```",
                "",
            ]
    OUT.write_text("\n".join(lines), encoding="utf-8")
    print(f"wrote {OUT.relative_to(OUT.parent.parent)}")
    return 0


if __name__ == "__main__":
    sys.exit(main())
